// Static curriculum content for the Theory tab — 150 concept cards, grouped
// by category below and interleaved into a single day-by-day schedule by
// buildTheorySchedule(). This is pure content (no DB), so it's imported
// directly by both the server and the frontend, same as scheduling.ts.

export type Category =
  | "System Design"
  | "Data Structures & Algorithms"
  | "Distributed Systems"
  | "Databases"
  | "Networking & OS"
  | "Behavioral";

export interface ConceptSeed {
  question: string;
  answer: string;
}

export interface Concept extends ConceptSeed {
  day: number;
  category: Category;
}

export const SYSTEM_DESIGN: ConceptSeed[] = [
  { question: "What problem does a load balancer solve, and what are the main algorithms it can use to pick a backend?", answer: "A load balancer's job is to spread incoming requests across several backend servers so that no single one gets overwhelmed while the others sit idle, and if one server goes down, the others can pick up the slack instead of the whole service failing. For example, imagine a website getting 10,000 requests per second: instead of sending them all to one server, the load balancer distributes them evenly using a strategy like round robin (rotating through servers one at a time), least connections (sending traffic to whichever server is currently least busy), or consistent hashing (always sending the same user to the same server, which helps when that server has cached their session data)." },
  { question: "When do you scale horizontally vs vertically, and what does each cost you?", answer: "When your system is under more load than it can handle, you can either make the existing machine bigger (vertical scaling) or add more machines (horizontal scaling). Vertical scaling is easy — just upgrade to a beefier server — but eventually you hit a ceiling on how big a single machine can get, and if that one machine dies, everything goes down with it. Horizontal scaling avoids that ceiling and gives you redundancy, but it's more work: for example, if you add a second web server, you now have to make sure user sessions aren't tied to just one machine, and that data gets split or synchronized correctly across both." },
  { question: "Compare cache-aside, write-through, and write-behind caching strategies.", answer: "These are three strategies for keeping a cache in sync with your database. With cache-aside, the app checks the cache first, and on a miss it fetches from the database and stores the result in the cache for next time — simple, but the very first request for any piece of data is always slow. With write-through, every write goes to the cache and the database at the same time, so reads are always up to date, though writes take a bit longer since two things have to happen. With write-behind, the write hits the cache immediately and gets saved to the database later in the background — for example, a 'like' counter on a social post might use write-behind so likes register instantly, accepting the small risk that a crash right before the background save could lose the most recent few." },
  { question: "What does a CDN actually do, and why does it help even for dynamic content?", answer: "A Content Delivery Network (CDN) stores copies of your content on servers scattered around the world, so a user's request gets served from a nearby location instead of traveling to your main server. This helps even for pages that change often, because most pages are made up of pieces — images, JavaScript, stylesheets — that don't change from request to request, and those pieces still benefit from caching. For example, a news site's headline text might update every few minutes, but its logo and CSS file can be served instantly from a CDN node in the reader's own city instead of a data center across the world." },
  { question: "In system design interviews, what does 'picking two out of three' really mean for CAP?", answer: "CAP theorem says that when part of your distributed system loses the ability to talk to another part — a network partition, which eventually happens no matter how good your network is — you have to choose between Consistency (every server gives you the exact latest data) and Availability (every server still responds, even if its data is a bit stale). For example, imagine a shopping cart split across two data centers that briefly lose connection: it can either keep accepting updates on both sides and reconcile them later (favoring availability), or refuse updates on one side until the connection is restored (favoring consistency). In practice, most real systems lean toward availability with tunable consistency, rather than treating it as a strict either/or." },
  { question: "What is consistent hashing and what problem does it solve over plain modulo hashing?", answer: "If you spread data across servers using a simple formula like 'hash(key) modulo number-of-servers,' adding or removing even one server changes the result for almost every key, forcing a huge, disruptive reshuffle of nearly all your data at once. Consistent hashing fixes this by arranging both servers and keys on a conceptual ring, so adding or removing a server only affects the keys sitting next to it on the ring, not everything else. For example, adding a new cache server with consistent hashing means only a small slice of keys need to move to it — the rest stay exactly where they were, avoiding a stampede of cache misses." },
  { question: "What are the main strategies for sharding a database, and what's the risk of each?", answer: "Sharding splits a database across multiple machines so no single one has to store or serve all the data, and there are a few common ways to decide what goes where. Range-based sharding keeps data in order (like splitting users by last name A-M and N-Z) — easy to understand, but if activity clusters around one range, that shard gets overloaded. Hash-based sharding spreads data evenly, avoiding hot spots, but scatters related rows so range queries like 'find all users from A to M' become expensive. Directory-based sharding uses a lookup table mapping each key to its shard, which is flexible for rebalancing, but that lookup table itself becomes an extra network hop and a critical piece of infrastructure that needs its own protection against failure." },
  { question: "Why add read replicas, and what problem do they introduce?", answer: "Read replicas are copies of your main database that only handle read queries, taking that load off the primary so it can focus on writes, and they can be placed closer to users in different regions to cut latency. The catch is replication lag: since replicas receive updates from the primary with a small delay, a user could write data and then immediately read from a replica that hasn't caught up, seeing stale information. For example, someone posts a comment and refreshes a split second later, not seeing their own comment yet — apps handle this by routing that user's very next read back to the primary." },
  { question: "Why put a message queue between two services instead of calling directly?", answer: "A message queue lets one service hand off work and move on immediately, without waiting for the second service to actually process it — it decouples the two, so the sender doesn't care if the receiver is slow, temporarily down, or hit with a sudden burst of work, since the queue holds messages until the receiver is ready. For example, when a user uploads a video, the upload service can drop a 'process this video' message on a queue and respond to the user right away, while a separate video-processing service works through the queue at its own pace. Queues also make it easy to fan out the same message to multiple interested services and to automatically retry messages that fail to process." },
  { question: "Explain token bucket and leaky bucket rate limiting and how they differ.", answer: "Both are ways to limit how many requests a client can make, but they smooth things out differently. Token bucket keeps a bucket that refills with tokens at a steady rate, and each request needs a token to proceed — if the bucket has built up tokens because the client was idle, that client can suddenly burst through several requests at once, up to the bucket's size. Leaky bucket makes every request wait in line and lets them out at a strictly constant rate, like water leaking from a hole in a bucket, smoothing bursts into a steady trickle instead of letting them through at once. For example, an API tolerating occasional spikes from a mobile app syncing after being offline would use token bucket, while one wanting perfectly steady load on a downstream system would use leaky bucket." },
  { question: "What is the circuit breaker pattern and what are its three states?", answer: "A circuit breaker protects your system from wasting time and resources repeatedly calling a downstream service that's already failing, the way an electrical breaker in your house cuts power before something overheats. Closed is the normal state, where requests flow through and failures are just being counted. Open kicks in after too many failures, stopping requests entirely and failing fast without even trying, giving the struggling service room to recover. Half-Open follows a cooldown, letting one trial request through to test if the service has recovered before fully reopening the gate. For example, if a payment provider starts timing out, a circuit breaker stops your checkout service from piling on more requests, so users get a quick error instead of a long hang." },
  { question: "What responsibilities does an API Gateway typically take on?", answer: "An API Gateway sits in front of all your backend services as the single front door every client request goes through, handling things that would otherwise need duplicating in every service: routing to the right backend, checking whether the caller is allowed to make the request, limiting how many requests a client can make, reshaping requests or responses, and sometimes combining several backend calls into one response. For example, a mobile app's 'home screen' request might need data from a user service, a recommendations service, and a notifications service — the gateway can call all three and merge the results into one response, so the app doesn't need three separate round trips." },
  { question: "Client-side vs server-side service discovery — what's the tradeoff?", answer: "Service discovery is how one service finds the current network address of another, since in a system where servers are constantly added, removed, or restarted, hardcoding addresses doesn't work. With client-side discovery, each client asks a shared registry like Consul or Eureka 'where is service X right now?' and picks a target itself — no extra network hop, but every client needs that lookup logic. With server-side discovery, a dedicated router does that lookup on the client's behalf, so clients stay simple, at the cost of an extra hop and one more piece of infrastructure that itself needs to stay highly available." },
  { question: "Why do idempotency keys matter for APIs that might be retried?", answer: "When a client sends a request and doesn't get a response — say the connection dropped — it has no way to know if the server actually processed it, so the safe move is to retry. But retrying a request like 'charge this credit card' could accidentally double-charge the customer if the first attempt actually succeeded. An idempotency key is a unique ID the client attaches so that if the server sees the same key twice, it recognizes it as a retry and just returns the original result instead of doing the work again — for example, ensuring a customer's flaky wifi never results in a double charge." },
  { question: "What is back-pressure and why does a fast producer need to respect it?", answer: "Back-pressure is a way for a slower part of the system to tell a faster part upstream to slow down, instead of getting flooded with more work than it can handle. Without it, a fast producer can pile up work faster than a consumer can process it, leading to a growing queue, memory running out, or requests getting dropped. For example, if a video-processing service can only handle 10 uploads per second but users are uploading 50 per second, back-pressure might mean the upload service starts rejecting or delaying new uploads once its queue fills up, rather than accepting unlimited uploads and crashing under the backlog." },
  { question: "Compare long polling, WebSockets, and Server-Sent Events for real-time updates.", answer: "These are three ways to push real-time updates to a client without constant page refreshes. Long polling has the client ask 'anything new?' and the server holds the request open until it has something to report, then the client asks again — simple and works almost everywhere, but there's overhead from constantly reopening requests. WebSockets open a single persistent, two-way connection so either side can send data instantly — very low latency, but more complex to run at scale, since a user's follow-up requests need to land on the same server holding their connection. Server-Sent Events let the server continuously push updates over a simple one-way HTTP connection — simpler than WebSockets when the client only needs to receive updates, like a live sports score ticker." },
  { question: "What's the difference between a forward proxy and a reverse proxy?", answer: "Both are middlemen sitting between two parties, but on opposite sides. A forward proxy sits in front of clients and acts on their behalf — for example, a company might route employees' internet traffic through a forward proxy to filter content or hide their individual identities from the websites they visit. A reverse proxy sits in front of servers instead — for example, nginx sitting in front of a cluster of backend servers so visitors only ever see the reverse proxy's address, with no idea which actual backend machine handled their request." },
  { question: "How do bloom filters help at scale, and what's their key limitation?", answer: "A bloom filter is a compact data structure that quickly answers 'is this item definitely not in the set?' or 'is this item maybe in the set?' using very little memory, letting you skip expensive lookups. For example, a database might check a bloom filter before hitting the disk: if it says 'definitely not here,' the slow disk read is skipped entirely, and the actual data is only checked when the filter says 'maybe.' The tradeoff is that it can occasionally give a false positive (wasting one lookup) but never a false negative, and you can't remove items from a standard bloom filter once they're added." },
  { question: "What's the difference between active-passive and active-active multi-region deployment?", answer: "These describe two ways of running a service across multiple regions for redundancy. Active-passive keeps one region handling all live traffic while a second sits on standby, only stepping in if the first fails — simple, but that standby capacity sits unused most of the time. Active-active has multiple regions all serving real traffic at once, using resources more efficiently and serving users faster by routing them to their nearest region — but for example, if a user in Europe and a user in the US update the same shared data at nearly the same moment on their regional servers, the system now has to detect and resolve that conflict, which is much harder than it sounds." },
  { question: "Walk through a rough back-of-envelope capacity estimate: how would you size servers for 10M daily active users?", answer: "This is about turning a vague requirement like '10 million daily active users' into a concrete server count. Start by estimating requests per user per day — say 20 — which gives 200 million total daily requests. Divide by the roughly 86,400 seconds in a day to get an average of about 2,300 requests per second, then multiply by a peak factor (say 3 to 5x, since traffic isn't evenly spread — everyone checks the app during lunch) to get true peak load. Finally, divide that peak number by how many requests a single server can handle under load testing, and add extra capacity as a safety margin, to arrive at a rough server count." },
  { question: "What's the difference between SLA, SLO, and SLI?", answer: "These three terms describe reliability at different levels of formality. An SLI (Service Level Indicator) is the actual number you measure, like 'our checkout page's 99th-percentile response time is 280ms.' An SLO (Service Level Objective) is the internal target you set for that number, like 'we want p99 latency under 300ms' — a goal your team holds itself to. An SLA (Service Level Agreement) is a promise made externally to customers, often contractual with financial penalties if broken — usually set looser than your internal SLO, so you have a buffer to catch problems before breaking an actual customer contract." },
  { question: "What is graceful degradation and how do feature flags support it under load?", answer: "Graceful degradation means that when a system is under heavy load, it deliberately turns off less important features to protect the core functionality that matters, rather than letting everything crash together. For example, an e-commerce site under a Black Friday surge might temporarily disable the 'customers also bought' widget so checkout — the part that actually makes money — keeps working smoothly. Feature flags make this practical: they're switches that let engineers turn a feature on or off instantly in production without deploying new code, sometimes automated to trigger when error rates or load cross a threshold." },
  { question: "Compare blue-green and canary deployment strategies.", answer: "These are two strategies for rolling out new software safely. Blue-green deployment runs two complete, identical environments side by side — the old version and the new — and switches all traffic over at once; if something goes wrong, you can instantly switch back, but you pay for two full sets of infrastructure during the transition. Canary deployment sends the new version to just a small slice of traffic first, watches for errors, and gradually ramps up if things look healthy. For example, a risky database change rolled out as a canary means only a small fraction of users are affected if there's a bug, before it's caught and rolled back — rather than everyone at once." },
  { question: "What's the core difference between event-driven architecture and request/response, and when would you pick each?", answer: "Request/response is the straightforward model where a caller sends a request and waits for an answer — easy to follow, good when the caller genuinely needs a result right away, like 'what's this user's account balance?' Event-driven architecture has services publish events without knowing who's listening, and other services react on their own time. For example, when an order is placed, the order service just publishes an 'order placed' event, and the inventory, email, and analytics services each react independently — this decouples them nicely and makes adding new reactions easy later, but makes tracing what happened across the system harder to debug, and different services may briefly see an inconsistent picture of the world." },
  { question: "Why does database indexing help system-scale design decisions, and what's the tradeoff of adding many indexes?", answer: "A database index works like a book's index: instead of scanning every row to find what you're looking for, you look it up directly, turning a slow scan into a fast, targeted lookup — this matters enormously once a table has millions of rows. But indexes aren't free: every index has to be updated whenever a row is written, so more indexes mean slower writes and more storage used, which is why you add indexes based on the queries you actually run — for example, indexing the 'email' column because your app constantly looks users up by email — rather than indexing every column just in case." },
  { question: "Design a URL shortener. What's the core approach and the main design decision?", answer: "A URL shortener generates a short, unique code for every long URL a user submits, then stores the mapping so it can redirect visitors later. For example, shortening 'https://example.com/a-very-long-article-title' might assign it the code 'x7Yq2', store 'x7Yq2 → https://example.com/...' in a fast key-value store, and redirect anyone who visits 'short.ly/x7Yq2' to the original page. The main design decision is how to generate that code: a sequential counter never collides but reveals how many links have been created and needs coordination across servers, while a random code needs a collision check but doesn't leak that information." },
  { question: "Design a rate limiter service usable by many downstream APIs. What would you clarify and what's the core component?", answer: "Before designing a shared rate limiter, you'd clarify what's being limited — per user, per IP, or per API key — and whether the limit needs to be perfectly precise or can tolerate a small overshoot for speed. The core piece is a fast, shared store like Redis holding a counter for each client, with an atomic 'increment and check' operation so all app servers check the same counter. For example, if a customer is limited to 100 requests per minute, every app server checks that same shared counter in Redis before allowing a request through, rather than each server tracking its own count and accidentally allowing 100 requests per server." },
  { question: "Design a distributed cache (like a Redis cluster). What are the key components?", answer: "Building something like a Redis cluster means solving several problems at once: consistent hashing to decide which server stores which key, replication so a shard's data survives that server dying, an eviction policy like LRU to decide what to discard when memory fills up, and a client library that knows the current shard layout. The central design question is trading consistency for speed: should a write wait for a backup replica to confirm (safer, slower) or return immediately after hitting just the primary (faster, but risks losing that write if the primary crashes before replicating it)?" },
  { question: "Design a unique ID generator for a distributed system (Snowflake-style). What goes into an ID?", answer: "A unique ID generator needs to hand out IDs that never collide across many servers generating them simultaneously, without a single central counter becoming a bottleneck. It does this by packing a timestamp (so IDs are roughly sortable by creation time), a machine ID (so two servers generating an ID at the same millisecond don't collide), and a sequence number (for multiple IDs from the same server in the same millisecond) into one number. For example, two servers can each generate thousands of IDs per second completely independently, with no chance of collision, since each ID encodes which machine made it." },
  { question: "Design a news feed / timeline system (like Twitter). What's the fan-out tradeoff?", answer: "When someone posts, you need to get it in front of all their followers, and there's a real tradeoff in how. Fan-out-on-write pushes the new post into every follower's precomputed feed immediately, so reading your feed is instant — but if a celebrity with 50 million followers posts, that's 50 million feed updates for one post, enormously wasteful. Fan-out-on-read builds your feed on the fly by pulling recent posts from everyone you follow — cheap to write, slower to read. Most real systems hybridize: fan-out-on-write for typical users, fan-out-on-read for huge accounts where fanning out at write time would be too expensive." },
  { question: "Design a chat application (like WhatsApp). What are the core components?", answer: "A chat app needs to track who's online and route messages to them in real time, typically via a persistent WebSocket connection held by a connection-gateway server for each online user. It also needs a message store for conversation history and offline delivery, plus a presence service tracking which gateway server holds each user's live connection — for example, so a message to a friend can be routed to 'gateway server #7' where their connection currently lives. Delivery and read receipts are tracked as separate state from the message itself, updated as those events happen." },
  { question: "Design a notification system that fans out to push, email, and SMS. What's the core architecture?", answer: "A notification system takes one event, like 'your order has shipped,' and gets it to the user through whichever channels make sense — push, email, text — while respecting the user's preferences and quiet hours. The typical design publishes the event to a queue; a notification service picks it up, checks the user's preferences, and hands it off to the right channel-specific provider, like Apple's push service, an email provider, or an SMS gateway. Each channel needs its own retry logic — for example, if the SMS provider is briefly down, that shouldn't block or delay the push notification and email from going out." },
  { question: "Design a web crawler. What are the key components and the main failure mode to guard against?", answer: "A web crawler systematically visits pages, follows their links to find more, and needs a few key pieces: a 'frontier' (queue of URLs waiting to be visited, prioritized by importance), a pool of fetchers that respect each site's rate limits and robots.txt, a dedup layer (often a bloom filter) to avoid re-crawling the same page, and a parser that extracts new links back into the frontier. The main danger is a 'crawler trap' — for example, a calendar page that links to 'next month' forever, generating an infinite stream of new URLs unless you set limits to catch it." },
  { question: "Design an autocomplete/typeahead search. What data structure and update strategy would you use?", answer: "Autocomplete needs to return matching suggestions fast enough to feel instant on every keystroke. A trie — a tree where each step down represents one more character typed — lets you find all suggestions for a prefix in time proportional to just how much has been typed, instead of scanning every possible term. Since rebuilding this from live search activity on every keystroke would be far too slow, real systems typically rebuild the suggestion index periodically, like once an hour, from aggregated query frequency data — so a suddenly trending search might take up to an hour to show up as a top suggestion rather than appearing instantly." },
  { question: "Design a distributed file storage system (like Dropbox/S3). What are the core layers?", answer: "A system like Dropbox or S3 splits its work into two layers: a metadata service that tracks a file's name, version history, permissions, and which chunks make up its content, and a separate blob storage layer holding the actual raw data, chunked and replicated across machines and regions for durability. Splitting large files into chunks also lets you upload or download pieces in parallel, and if two different files happen to share an identical chunk — a common photo edited slightly, for example — the system can store that chunk once and reference it from both instead of duplicating it." },
  { question: "Design a video streaming service (like YouTube). What's the role of transcoding and adaptive bitrate?", answer: "When a video is uploaded, it gets transcoded — converted — into several resolutions and bitrates, and each is split into short segments a few seconds long. As you watch, the player continuously checks your network speed and requests the segment quality that best matches it — adaptive bitrate streaming — so if your wifi suddenly slows down, the player drops to a lower quality on the next segment instead of buffering endlessly, then switches back up once your connection improves. A CDN then serves those segments from a location close to you, further cutting delay." },
  { question: "Design a ride-sharing matching system (like Uber). What's the core matching approach?", answer: "A ride-sharing system needs to quickly figure out which nearby drivers could pick up a rider, out of thousands across a city. It uses a geo-index — often a grid or a technique like geohashing — so instead of checking distance to every driver in the city, it only checks drivers within the rider's immediate area. From that shortlist, it ranks candidates by estimated arrival time and matches with something like 'assign the nearest available driver,' though some systems batch riders and drivers together for a more fair or efficient overall matching. All of this depends on driver locations streaming in continuously with very low delay, since a position from 30 seconds ago might already be wrong." },
  { question: "Design an e-commerce checkout and inventory system. What's the trickiest consistency problem?", answer: "The hardest problem is preventing overselling — making sure that if there's only one item left, two customers hitting 'buy' at nearly the same moment can't both succeed. One solution reserves the item the moment someone adds it to their cart or starts checkout, holding that reservation for a limited time so it releases automatically if they never complete payment. Another lets the database enforce it with a conditional update, like 'decrease stock by 1, but only if stock is currently greater than 0,' so if two requests race, only one succeeds and the other is told the item is out of stock." },
  { question: "Design a payment processing system. What design principle is non-negotiable and why?", answer: "The one thing you cannot compromise on is idempotency — ensuring that if a network hiccup causes a client to retry a charge, the customer never gets billed twice. This is done by attaching a unique idempotency key to every payment request, so the system recognizes a repeat and returns the original result instead of charging again, even across a server crash and restart. Payments also typically use the saga pattern to coordinate multi-step processes like 'charge the card, then fulfill the order, then send a confirmation email' — if a later step fails, the saga runs compensating actions like refunding the charge, rather than leaving things half-finished." },
  { question: "Design a leaderboard for a game with millions of players. What data structure powers real-time ranking?", answer: "A leaderboard needs to answer 'who are the top 10 players right now?' or 'what rank is this player?' extremely fast as scores keep changing. A sorted set, like Redis's ZSET, keeps items automatically ordered by score and answers both questions in logarithmic time — far faster than a relational database, which would need heavy, constantly-updated indexes to do the same at this scale. For example, a game with 10 million players might shard its leaderboard by region or mode, so 'top players in Europe, Ranked mode' stays a manageable size rather than trying to rank all 10 million players in one giant list." },
  { question: "Design a distributed job scheduler (like cron at scale). What problem does it solve beyond a single-node cron?", answer: "A distributed job scheduler solves a problem a simple cron job on one machine doesn't have: making sure a scheduled task runs exactly once, even with many worker machines that could all try to run it at the same time. This is typically solved by electing one scheduler as the leader, so only it triggers scheduled jobs, or with a distributed lock specific to each job that only one worker can acquire. It also needs to persist its schedule, so if the leader crashes and a new one takes over, no scheduled job is silently forgotten — for example, a nightly billing job needs to run reliably even if the server that was supposed to trigger it restarted at 11:59pm." },
  { question: "Design a distributed logging/monitoring pipeline. What's the general data flow?", answer: "A distributed logging pipeline follows a general pattern: small agents on each server ship logs and metrics to a durable buffer, like a message queue, which smooths out sudden spikes in volume. From there, processing services consume that data, aggregate and index it into a queryable store — a time-series database for metrics, a search index for logs — and finally dashboards and alerting query that store. For example, if a service suddenly produces ten times more error logs during an incident, the buffer absorbs that burst so downstream processors aren't overwhelmed and can keep working through the backlog without crashing." },
  { question: "At a high level, what are the main components behind a search engine's ranking backend?", answer: "A search engine starts with a crawler and indexer that build an inverted index — essentially a giant lookup table mapping each word to every document containing it. When you search, the engine uses that index to pull a set of candidate documents, then ranks them with a scoring function combining signals like how often your terms appear, how many pages link to that page, how recent it is, and personalization. Because scoring every candidate with the full model would be too slow, engines often use two passes: a cheap first pass narrows thousands of candidates to a few hundred, then a more expensive model re-ranks just that smaller set." },
  { question: "Design an uptime/health-check monitoring system for thousands of URLs. What's the core loop?", answer: "An uptime monitor spreads its URL list across a pool of checker workers, often in different regions, each pinging its assigned URLs on a regular interval and recording whether they responded and how fast. Using multiple regions matters because it helps distinguish a real outage from a purely local network problem — if a checker in Tokyo can't reach a site but checkers elsewhere can, that's likely a network issue near Tokyo, not the site actually being down. So the aggregator waits for failures confirmed by multiple independent regions before alerting, avoiding false alarms from one checker's own connectivity blip." },
  { question: "Design a collaborative document editor (like Google Docs). What's the core technique for merging concurrent edits?", answer: "A collaborative editor needs multiple people typing into the same document at once, all ending up seeing the same final result, without anyone waiting their turn or locking the document. This is solved with techniques like Operational Transformation or CRDTs (Conflict-free Replicated Data Types), mathematical approaches for merging concurrent edits automatically and predictably regardless of the order they arrive in. For example, if two people each delete a different word in the same sentence at the same moment, the system figures out how to apply both deletions correctly so everyone converges to the same text — and each keystroke is sent as a tiny operation, not the entire document every time." },
  { question: "Design a ticket-booking system (like Ticketmaster) that must never oversell a seat. What's the concurrency approach?", answer: "A ticketing system can't let two people both successfully book the same seat, so it treats reserving a seat as a single atomic operation — something like 'mark this seat reserved, but only if it's currently available.' If a thousand people click 'buy' on the same seat within the same second, only one request wins because the database itself enforces that only one update can succeed; everyone else is immediately told the seat is taken, rather than queued and finding out minutes later. Once reserved, the seat gets a short time limit, like 10 minutes, to complete payment, and if the buyer doesn't finish in time, it becomes available again automatically." },
  { question: "Design a key-value store from scratch. What are the core building blocks?", answer: "Building a key-value store requires a few core pieces working together. A partitioning scheme, usually consistent hashing, decides which server stores which keys, spreading data evenly across the cluster. Replication keeps multiple copies of each piece of data on different servers so a single server failure doesn't lose anything. A quorum scheme balances consistency and availability by requiring a certain number of servers to confirm a read or write, designed so a read always sees the latest write as long as the read and write quorums overlap by at least one server. Each server also needs its own storage engine, often something called an LSM-tree, optimized for handling a heavy stream of writes efficiently." },
  { question: "Design a 'like' counter for posts that need to handle huge write volume. Why not just UPDATE a counter column directly?", answer: "Directly updating a single counter column every time someone likes a post seems obvious, but under massive concurrent write volume — imagine a viral post getting thousands of likes per second — every one of those writes fights for a lock on that exact same row, creating a serious bottleneck. Instead, systems often batch likes in a fast in-memory store or a temporary write buffer, periodically flushing the aggregated total to the real database rather than hitting it on every click. Another trick is sharding the counter into multiple separate rows and simply summing them when displaying the total, spreading the write load across rows instead of one hot row." },
  { question: "Design an ad click-tracking and analytics pipeline. What's the core tradeoff in how you process events?", answer: "An ad click-tracking pipeline has to choose between two ways of processing events. Stream processing, using tools like Kafka feeding a stream processor, gives advertisers near-real-time numbers on their campaign — but it's genuinely hard to get right, since you have to handle events arriving late or out of order and avoid double-counting the same click. Batch processing collects events and processes them together on a schedule, like once an hour — much simpler to build correctly, but the numbers advertisers see are hours old. Many real systems run both: a fast, slightly-approximate real-time path for dashboards, and a slower, exact batch process that reconciles the numbers later." },
  { question: "Design a public API platform with per-customer quotas and billing. What's the core architectural addition over a plain API?", answer: "Turning a plain API into a paid, rate-limited platform requires adding a metering and gateway layer on top. This layer authenticates every incoming request to figure out which customer it belongs to, checks it against that customer's quota using the same kind of shared rate limiter used elsewhere, and durably logs the usage for billing purposes. That usage logging needs to be extremely reliable — for example, if a customer's request ultimately fails partway through, you might still need to bill them for the attempt, so the record of 'this request happened' has to survive even if request processing crashes right afterward." },
];

export const DSA: ConceptSeed[] = [
  { question: "What does Big-O actually describe, and what's a common mistake people make when reasoning about it?", answer: "Big O stands for \"Order of\", meaning the order of growth of an algorithm as the input size (n) increases. That is why it is commonly written as O(n), where n represents the size of the input. We use Big O notation to describe both time complexity (how the running time grows) and space complexity (how the memory usage grows). For example, in the Two Sum problem, the brute-force approach uses two nested loops: one pointer selects the current element, while the other checks every remaining element. This results in O(n²) time complexity because we perform roughly n × n comparisons. However, if we use a hash map, we only need to traverse the array once, giving a time complexity of O(n). The brute-force approach has a space complexity of O(1) because it only uses a fixed number of variables, whereas the hash map approach has a space complexity of O(n) because the hash map grows proportionally with the size of the input array." },
  { question: "What are the practical tradeoffs between arrays and linked lists?", answer: "Arrays and linked lists both store a list of items, but they trade off speed in different places. An array stores its elements next to each other in memory, so you can jump straight to any position instantly, like jumping to page 50 of a book, and because the data sits close together the computer's cache handles it efficiently — but inserting or removing something from the middle means shifting every element after it, which gets slow for big lists. A linked list stores each element separately with a pointer to the next one, so inserting or removing is instant once you're already at that spot, like pulling one link out of a chain — but finding a specific element means walking through the list one link at a time from the start, and because the pieces are scattered in memory, it's slower for the computer to access." },
  { question: "How does a hash table resolve collisions, and what are the two main strategies?", answer: "A hash table needs a plan for when two different keys hash to the same slot — a collision — and there are two common approaches. Chaining keeps a small list at each slot, so if two keys collide, they both just get added to that slot's list; it's simple and degrades gracefully, but each slot uses a bit of extra memory for that list structure. Open addressing instead finds a different empty slot nearby when a collision happens, checking the next slot, or the one after, using some pattern — this keeps everything packed together in one array, which is friendlier to the CPU cache, but removing an item gets trickier, and things slow down noticeably once the table gets too full." },
  { question: "When would you reach for a stack vs a queue?", answer: "The choice comes down to what order you need to process things in. A stack is 'last in, first out' — the most recently added item is handled first — which fits situations like undoing your most recent action, matching pairs of parentheses in code, or how function calls work when one function calls another. A queue is 'first in, first out' — items are handled in the order they arrived — which fits things like a print queue, where the first document sent should print first, or processing a breadth-first search level by level." },
  { question: "What preconditions does binary search require, and what's the classic off-by-one bug?", answer: "Binary search only works if the thing you're searching through is sorted, or otherwise has some predictable order, because the whole trick depends on throwing away half the remaining possibilities at each step based on a single comparison. A classic bug happens when the boundaries used to narrow the search don't match up consistently — for example, computing the middle index and then setting the new high boundary to that same middle index instead of one less than it, which can cause the search to loop forever or skip right over the answer sitting at the edge of the range." },
  { question: "What is the two-pointer technique and what kind of problems does it solve efficiently?", answer: "The two-pointer technique uses two positions moving through a sorted array or string — often starting from opposite ends and moving toward each other, or one moving faster than the other — to avoid comparing every possible pair, which would take much longer. For example, to find two numbers in a sorted array that add up to a target value, you can start one pointer at the beginning and one at the end: if their sum is too big, move the right pointer left; if too small, move the left pointer right — finding the answer in a single pass instead of checking every pair. The same idea powers detecting a cycle in a linked list, where a 'slow' and a 'fast' pointer moving at different speeds will eventually meet if there's a loop." },
  { question: "What is the sliding window technique and when does it apply?", answer: "The sliding window technique keeps track of a contiguous chunk of an array or string and slides its edges forward incrementally, reusing work from the previous step instead of starting over each time — this turns a slow approach that checks every possible sub-range into something much faster. For example, to find the longest substring in a piece of text with no repeated characters, you can expand a window to the right one character at a time, and only shrink it from the left when a repeat shows up, rather than re-checking every possible substring from every starting point." },
  { question: "What distinguishes a binary search tree from a plain binary tree?", answer: "A plain binary tree just means each node has up to two children — there's no rule about how the values relate to each other. A binary search tree (BST) adds one crucial rule: every value in a node's left subtree is smaller than the node, and every value in its right subtree is larger. That single ordering rule is what makes searching fast — at each node, you can tell instantly whether to go left or right, similar to narrowing down a name in a phone book by flipping to roughly the right section — whereas a plain binary tree gives no such shortcut and might require checking every node." },
  { question: "Why does an unbalanced BST hurt performance, and how do AVL/Red-Black trees fix it?", answer: "If you insert already-sorted data into a plain binary search tree — say, inserting 1, 2, 3, 4, 5 in order — every new value ends up as the right child of the previous one, turning the tree into essentially a straight line, no better than a linked list, so lookups become slow instead of fast. AVL trees solve this by automatically rotating nodes to keep both sides of any subtree within one level of height of each other, guaranteeing things stay balanced. Red-Black trees solve the same problem with a looser coloring rule that doesn't keep things quite as perfectly balanced, but needs fewer rotations on average to maintain, making insertions and deletions a bit cheaper in practice." },
  { question: "What is a heap, and why is it the right structure for a priority queue?", answer: "A heap is a tree-shaped structure that keeps one guarantee at all times: every parent node is either always smaller than its children (a min-heap) or always larger (a max-heap). That guarantee means you can grab the smallest or largest item instantly, and adding or removing an item only takes a small number of steps to restore the property afterward. This makes it perfect for a priority queue — for example, an emergency room triage system that always needs to see the most critical patient next can use a heap to instantly pull the highest-priority patient, without needing the entire waiting list to stay fully sorted." },
  { question: "What is a trie and what makes it well-suited to prefix-based lookups?", answer: "A trie stores words by breaking them into individual characters and building a tree where each step down represents typing one more letter, so words that share the same starting letters also share the same path through the tree. This is what makes it so good at prefix-based lookups like autocomplete: to find every word starting with 'pro', you just walk down the path for p-r-o and collect everything below that point, rather than checking every single word in your dictionary. The tradeoff is that a trie can use noticeably more memory than a simple list of words, since it needs a tree node for essentially every character position." },
  { question: "Adjacency list vs adjacency matrix for representing a graph — when does each win?", answer: "These are two ways to represent the connections in a graph, like a social network's friendships. An adjacency list stores, for each node, just a list of the nodes it's connected to — this uses memory proportional to the actual number of connections, and is efficient for looking up 'who is this person friends with,' which is common in sparse graphs where most nodes aren't connected to most others. An adjacency matrix instead stores a full grid where every possible pair of nodes has an entry marking whether they're connected — more memory regardless of how many connections actually exist, but answering 'are these two nodes connected?' is instant, which matters more in dense graphs." },
  { question: "BFS vs DFS — how do you decide which to use?", answer: "BFS (breadth-first search) explores a graph one full layer at a time, like ripples spreading out from a point in water, using a queue — this is the right tool for shortest path in a graph where all connections are treated equally, like finding the fewest hops between two people in a social network. DFS (depth-first search) instead follows one path as deep as it can go before backtracking, using a stack or recursion — this fits detecting whether a graph has a cycle, ordering tasks based on dependencies, or exhaustively exploring a maze, where you want to fully commit to one direction before trying another." },
  { question: "What does Dijkstra's algorithm compute, and what's its key limitation?", answer: "Dijkstra's algorithm finds the shortest path from one starting point to every other point in a graph where each connection has a weight or cost, like calculating driving distances between cities. It works by always expanding outward from whichever unvisited location is currently closest, using a priority queue to efficiently pick that next-closest location each step. Its key limitation is that it breaks down with negative edge weights — a 'path' that somehow subtracts distance instead of adding it — because its core assumption that distances only grow as you travel further no longer holds; for graphs with negative weights, you'd need a different, slower algorithm like Bellman-Ford instead." },
  { question: "What is topological sort and what precondition must the graph satisfy?", answer: "Topological sort produces an ordering of items in a graph such that if item A points to item B, meaning A must come before B, then A always appears before B in the final list — exactly what you need for scheduling tasks that depend on each other, like figuring out a valid order to take college courses when some require others as prerequisites. It only works if the graph is a DAG — a Directed Acyclic Graph, meaning connections all point one direction and never loop back — because if there's a cycle, like course A requiring course B which requires course A, there's no valid order that satisfies everything." },
  { question: "What problem does Union-Find (Disjoint Set) solve efficiently, and what two optimizations make it fast?", answer: "Union-Find, also called Disjoint Set, efficiently answers 'are these two items in the same group?' and lets you merge groups together, without tracking every single connection between every pair of items. For example, it's used in building a minimum spanning tree for a road network: as you consider adding roads one at a time, Union-Find quickly tells you whether connecting two towns would create a redundant loop, since they're already connected through other roads. Two optimizations make it extremely fast: union by rank/size always attaches the smaller group under the larger one to keep the structure shallow, and path compression flattens the structure further on every lookup, so future lookups become nearly instant." },
  { question: "How do you recognize that a problem should be solved with dynamic programming?", answer: "You know a problem is a good candidate for dynamic programming when it has two properties. First, optimal substructure: the best overall solution can be built by combining the best solutions to smaller versions of the same problem, like the shortest path to a destination being built from shortest paths to points along the way. Second, overlapping subproblems: a naive recursive solution ends up solving the exact same smaller problem over and over — for example, computing Fibonacci numbers recursively recalculates fib(2) hundreds of times on the way to fib(20). When both hold, dynamic programming saves subproblem results the first time they're solved, turning an exponential-time approach into something much faster." },
  { question: "What's the difference between memoization and tabulation?", answer: "Both are ways to implement dynamic programming, just built in opposite directions. Memoization is top-down: you write the natural recursive version of the solution, and add a cache that remembers the answer to each subproblem the first time it's computed, so a repeat is an instant lookup instead of redoing the work. Tabulation is bottom-up: instead of recursion, you build a table starting from the smallest subproblems and work your way up iteratively — for example, computing Fibonacci numbers by filling in fib(1), fib(2), fib(3), and so on in a loop, which avoids the overhead of function calls and the risk of running out of stack space on deep recursion." },
  { question: "When does a greedy algorithm give the correct (optimal) answer?", answer: "A greedy algorithm makes the choice that looks best right now at each step, without ever reconsidering it later — this only produces the actual best answer for problems where making the locally best choice at each step is guaranteed to lead to the globally best result. For example, scheduling as many non-overlapping meetings as possible in one room, always picking the meeting that ends soonest at each step genuinely gives the maximum number of meetings. But greedy fails on problems like packing a knapsack with the most valuable combination of items under a weight limit, where grabbing the seemingly best item first can block a better combination overall — one heavy, high-value item might use up all your remaining capacity, when two lighter items together would have been worth more." },
  { question: "What is backtracking, and how does it differ from plain brute-force recursion?", answer: "Backtracking builds up a solution piece by piece, but as soon as it realizes a partial solution can't possibly be completed successfully, it abandons that path immediately and tries something else — this is different from brute force, which would keep building out every possibility all the way to the end before checking if it's valid. For example, when solving a Sudoku puzzle, backtracking places a number, and if it later creates a conflict a few steps down the line, it undoes recent choices rather than filling in the entire remaining grid first only to discover it was invalid. This early pruning is what makes backtracking dramatically faster than pure brute force." },
  { question: "What is the divide-and-conquer paradigm, and what's a classic example?", answer: "Divide and conquer solves a problem by splitting it into smaller, independent subproblems of the same type, solving each one recursively, then combining their results into the final answer. Merge sort is the classic example: it splits an array in half, recursively sorts each half completely independently of the other, then merges the two sorted halves back together in order. This approach works best when the subproblems genuinely don't depend on each other and combining the results back together is cheap relative to solving each half." },
  { question: "Compare merge sort and quicksort — when would you prefer one over the other?", answer: "Both sort a list in roughly n log n time on average, but they make different tradeoffs. Merge sort guarantees n log n performance no matter what the input looks like and is 'stable,' meaning equal elements keep their original order — but it needs extra memory proportional to the array's size to do the merging. Quicksort is usually faster in practice because it works in place with better cache behavior, but its worst case can degrade to n² if it consistently picks bad pivot points, like sorting an already-sorted array with a naive 'always pick the first element' strategy — which is why real implementations pick pivots randomly or use a smarter strategy to avoid that worst case." },
  { question: "What's the practical tradeoff between recursion and iteration?", answer: "Recursion often makes certain problems — especially ones involving trees, graphs, or nested structures — much easier to read and write, since the code can mirror the structure of the problem itself. But every recursive call adds a new frame to the call stack, and if the recursion goes too deep, like processing a very deeply nested structure, you can run out of stack space and crash. Iteration avoids that overhead and risk entirely, but sometimes you have to manually manage state that recursion would have tracked for you — for example, converting a recursive depth-first search into an iterative one means manually maintaining your own stack to remember where to backtrack to." },
  { question: "Give an example of a bit-manipulation trick and what it's used for.", answer: "One classic trick is `n & (n-1)`, which clears the lowest set bit — the rightmost 1 — in a number's binary representation. This is useful for counting how many bits are set to 1 in a number: instead of checking every bit position one at a time, you repeatedly apply this trick and count how many times it takes to reduce the number to zero, which is faster when the number has only a few 1 bits. The same trick gives a quick way to check whether a number is a power of two, since powers of two have exactly one bit set, meaning `n & (n-1)` equals zero exactly when that's the case." },
  { question: "How would you design an LRU cache with O(1) get and put?", answer: "An LRU (Least Recently Used) cache needs to do two things fast: look up a value by key, and evict the item that hasn't been used in the longest time when the cache is full. You get both by combining a hash map, which gives instant lookup from key to location, with a doubly linked list that keeps items ordered by how recently they were used — every access moves an item to the front, and when the cache is full, the item at the back gets evicted. For example, a cache that can only hold 100 recently viewed images uses this structure so looking up, marking as just-used, and evicting the oldest are all instant, instead of searching the whole list to find the oldest entry." },
  { question: "What problem do segment trees / Fenwick (BIT) trees solve that a plain array can't do efficiently?", answer: "A plain array is fast at either updating a single value or answering a query over a range of values, but not both at once — updating one element is instant, but summing a range of a thousand elements means checking all of them, unless you precompute the sums in advance, in which case a single update now means recomputing everything downstream of it. Segment trees and Fenwick (Binary Indexed) trees solve this by organizing data into a tree-like structure where both a range query, like 'what's the sum of elements 10 through 50,' and a single-element update take a fast, roughly logarithmic amount of time — useful for something like a running leaderboard where scores change frequently and you also need range queries, like the total score of players ranked 10 through 20." },
  { question: "How does a bloom filter achieve O(1) 'possibly present' checks, and why can't it have false negatives?", answer: "A bloom filter checks whether an item might be in a set by running it through several hash functions, each pointing to a position in a shared bit array, and flipping those positions to 1 when the item is added. To check an item later, it just checks whether all of that item's bit positions are still set to 1 — if even one isn't, the item definitely was never added, but if they're all set, it's a good sign it probably was, or possibly a coincidence from other items sharing those same bits, hence the risk of a false positive. It can never give a false negative, though, because if an item really was inserted, all of its bits were definitely set at that time, and nothing ever un-sets a bit." },
  { question: "What is a skip list and what does it offer over a balanced BST?", answer: "A skip list is built from multiple layers of linked lists stacked on top of each other, where higher layers skip over more elements, letting you quickly jump close to where you're looking before dropping to a lower, more detailed layer to pinpoint the exact spot — similar to an express train that only stops at major stations getting you roughly where you're going faster than a local train stopping everywhere. Which layer each element ends up in is decided randomly, essentially a coin flip, rather than through the careful rebalancing a balanced BST needs, which makes a skip list noticeably simpler to implement correctly, especially when multiple threads read and write it at once — at the cost of its guarantees being probabilistic rather than absolute." },
  { question: "What is amortized analysis, and what's the classic example?", answer: "Amortized analysis looks at the average cost of an operation over a long sequence of operations, rather than obsessing over the worst possible cost of any single operation, because sometimes an occasional expensive operation is rare enough that it barely affects the average. The classic example is a dynamically resizing array, like Java's ArrayList: appending an item is usually instant, but occasionally the array runs out of room and has to allocate a bigger block of memory and copy every existing element over, which is slow. But because each resize doubles the array's capacity, these expensive resizes become exponentially rarer as the array grows, so averaged across many appends, it still works out to roughly constant time per append." },
  { question: "What does 'NP-complete' mean in practical terms for an engineer?", answer: "When a problem is labeled 'NP-complete,' it means nobody has ever found an algorithm that solves it efficiently for all possible inputs, and if someone did find one, it would prove that an enormous class of hard problems can also be solved efficiently — something computer scientists have tried and failed to prove or disprove for decades. In practical terms, it's a signal not to waste time searching for a fast, perfectly exact algorithm — for example, if you're trying to find the absolute optimal delivery route for a truck visiting 50 cities, a version of the classic 'traveling salesman problem,' you should reach for a heuristic or approximation that gets a good-enough answer quickly, rather than expect an exact solution to be feasible beyond genuinely small inputs." },
];

export const DISTRIBUTED: ConceptSeed[] = [
  { question: "What problem do consensus algorithms like Paxos and Raft solve?", answer: "Paxos and Raft are algorithms that help a group of servers agree on the same information, even though the same data is stored across multiple servers. When one server receives an update, the algorithm makes sure the other servers agree on that update before it's saved, keeping every server in sync. This way, if one server crashes or the network is slow, both algorithms still make sure the system stays consistent and reliable." },
  { question: "Compare two-phase commit and the saga pattern for distributed transactions.", answer: "These are two ways to keep a transaction consistent when it spans multiple separate services or databases. Two-phase commit uses a coordinator that first asks every participant 'are you ready to commit?' and only tells everyone to actually commit if all say yes — strongly consistent, but if the coordinator or any participant crashes mid-protocol, everyone else can get stuck waiting indefinitely, and it doesn't scale to many services well. The saga pattern instead breaks the transaction into a sequence of local transactions, each with its own predefined 'undo' action — for example, booking a flight might reserve a seat, then charge a card, then send a confirmation, and if the charge fails, the saga runs the seat reservation's undo action to release it. This avoids blocking across services, but is only eventually consistent, and you have to write all that undo logic yourself." },
  { question: "What problem do vector clocks solve that a simple timestamp can't?", answer: "A regular timestamp can't reliably tell you which of two events on different machines happened first, because clocks on different machines are never perfectly synchronized and can drift apart. A vector clock solves this by giving every node its own counter, and each event carries a snapshot of all the counters it's aware of — comparing two of these vectors lets you determine with certainty whether one event happened strictly before another, strictly after, or whether they were truly concurrent with no causal relationship at all, which a single number could never tell you. For example, two users editing a shared document from different servers might make changes a vector clock reveals were genuinely simultaneous, meaning the system needs to merge them rather than assume one came first." },
  { question: "What is the gossip protocol and why is it useful for large clusters?", answer: "In a gossip protocol, each node periodically picks a few random other nodes and shares what it currently knows with them, and information gradually spreads across the entire cluster the way a rumor spreads through a group of people — surprisingly quickly, in only a small number of rounds relative to the cluster size. This is useful for large clusters because there's no single central node coordinating everything, so there's no bottleneck or single point of failure, it scales well as you add more nodes, and it naturally tolerates some nodes being down or slow. For example, Cassandra uses gossip so every node can independently learn which other nodes are alive or have failed, without asking a central authority." },
  { question: "What does the quorum condition R + W > N guarantee in a replicated data store?", answer: "When you keep N copies of a piece of data spread across different servers, you can choose how many need to confirm a read (R) and how many need to confirm a write (W) before that operation succeeds. If R + W is greater than N, then mathematically, any set of servers you read from must overlap with any set touched by a previous write by at least one server — guaranteeing your read always sees the most recent write. For example, with 5 replicas, requiring 3 to confirm every write and 3 to agree on every read (3+3=6 > 5) guarantees strong consistency without waiting on all 5 replicas, giving some slack to tolerate a couple of slow or unreachable ones." },
  { question: "How should a distributed system handle a network partition, and what's the core decision it forces?", answer: "When part of a distributed system suddenly can't communicate with another part, each side has to decide how to behave without knowing what the other side is doing, and the CAP theorem says this forces a real choice. One option is to keep serving requests on both sides, keeping the system available but risking the two sides accepting conflicting writes that need reconciling once the partition heals. The other option is for the side that can't confirm it has a majority to simply refuse requests until the partition resolves, sacrificing availability there but guaranteeing nothing inconsistent gets written. For example, a banking system might refuse withdrawals on a minority partition rather than risk two branches both approving withdrawals that overdraw an account." },
  { question: "What is split-brain and why is it dangerous?", answer: "Split-brain is a dangerous situation where a network partition causes two different nodes to each independently believe they're the one true leader, and both start accepting writes at the same time — since they can't see each other, neither realizes there's a conflict. By the time the partition heals, you can end up with two divergent, contradictory histories that need reconciling, potentially losing or corrupting data. Systems typically prevent this by requiring a leader to be confirmed by a majority vote of the cluster before it can act — since a network partition can only give a true majority to at most one side, split-brain becomes impossible as long as that rule is enforced strictly." },
  { question: "Multi-leader vs single-leader replication — what's the core tradeoff?", answer: "Single-leader replication routes every write through one designated node, keeping things simple since there's never any ambiguity about ordering — but that leader is a bottleneck for write throughput and a single point of failure until a new leader is elected if it goes down. Multi-leader replication allows writes to go to several leader nodes at once, for example one per geographic region so users write to whichever is closest — improving write availability and speed, but now two leaders in different regions could accept conflicting writes to the same data at nearly the same moment, and the system needs a strategy like 'last write wins' or custom merge logic to resolve that conflict." },
  { question: "Explain 'read-your-writes' and 'monotonic reads' as eventual-consistency guarantees.", answer: "These are two guarantees systems can offer even when they're not fully consistent. 'Read-your-writes' means that after you make a change, you'll always see it reflected on your next read, even if the server happens to be reading from a replica that's normally a little behind — often achieved by routing your very next read back to the primary briefly. 'Monotonic reads' means that once you've seen a certain version of the data, you'll never see an older version on a later read — you won't go back in time. For example, without monotonic reads, refreshing a page twice in a row could show you a comment, then not show it, then show it again, simply because your two refreshes happened to hit two replicas at different points in catching up." },
  { question: "What is distributed tracing and what problem does it solve in a microservices architecture?", answer: "In a microservices system, a single user request might touch ten different services before it's done, and if something is slow or breaks, figuring out which one was the culprit is hard if you're only looking at each service's separate logs. Distributed tracing solves this by attaching a single trace ID to the request at the start and passing it along through every service it touches, with each service recording how long it spent — so you can reconstruct the entire journey as one connected timeline. For example, if a checkout request takes 3 seconds total, a trace might reveal that 2.8 of those seconds were spent waiting on one slow call to the inventory service, immediately pointing you at the problem." },
  { question: "What is a service mesh and what does the sidecar pattern give you?", answer: "A service mesh handles networking concerns that every service would otherwise need to implement itself — retrying failed requests, encrypting traffic, load balancing, collecting metrics — by deploying a small proxy called a 'sidecar' alongside every service instance, which intercepts and manages all its network traffic. This means the application code doesn't need to know anything about retries or encryption at all; it just talks normally, and the sidecar handles it transparently. A central control plane configures all these sidecars consistently — for example, rolling out a new retry policy across 50 microservices means configuring it once centrally instead of changing code in 50 separate codebases." },
  { question: "Explain the difference between at-least-once, at-most-once, and exactly-once delivery.", answer: "These describe what a messaging system promises about whether a message gets delivered and how many times. At-most-once means a message might get lost but will never be delivered twice — a fire-and-forget notification where losing an occasional one is acceptable. At-least-once means a message is never lost but might be delivered more than once, for example if the sender doesn't hear an acknowledgment in time and resends it just in case. Exactly-once — delivered precisely once, no more, no less — is genuinely hard to guarantee, so in practice most systems settle for at-least-once delivery combined with making sure the receiver can safely handle the same message twice without harm." },
  { question: "Why must event consumers in a distributed system be idempotent?", answer: "Because most real messaging systems only promise at-least-once delivery, a consumer has to expect it will occasionally receive the same message twice — for example, if the sender didn't get an acknowledgment back in time due to a network hiccup and resent it just to be safe, even though the first copy was actually processed successfully. If processing that message twice would cause a problem, like charging a customer's card again, the consumer itself needs to detect and skip duplicates, typically by keeping a log of message IDs it's already handled and checking against it before doing any work." },
  { question: "Why can't distributed systems just rely on synchronized clocks, and what do they use instead?", answer: "You might think distributed systems could just rely on every server's clock being synchronized to know event order, but even clocks kept in sync using NTP can drift apart by tens of milliseconds and can occasionally jump backward, which would be disastrous for anything relying on strict ordering. Instead, distributed systems typically use logical clocks — like Lamport timestamps or vector clocks — which track event order based purely on the actual messages sent between machines, completely independent of what each machine's physical clock says. Some advanced systems, like Google Spanner, use a hybrid approach called TrueTime that combines GPS and atomic clocks with an explicit, bounded uncertainty window instead of pretending clocks are perfectly accurate." },
  { question: "What are the main approaches to leader election in a distributed system?", answer: "There are a few common ways distributed systems pick a leader among a group of nodes. The bully algorithm has every node compare IDs, and the highest-ID node simply declares itself leader with others deferring — simple, but that node could be inconveniently overloaded. Raft uses randomized timeouts: nodes wait a random amount of time, and whichever times out first becomes a candidate and asks others to vote for it, becoming leader if it wins a majority — this avoids two nodes starting an election at the same moment most of the time. Or a system can delegate the whole problem to an external coordination service like ZooKeeper or etcd, which provides leader election as a built-in feature using ephemeral nodes that automatically disappear if the leader crashes, signaling it's time for a new election." },
  { question: "Why are distributed locks hard to get right, and what's a common failure mode?", answer: "Distributed locks are tricky because of a specific failure mode: a node acquires a lock, then experiences a pause — a garbage collection pause, or a slow network — long enough for the lock's time-limited lease to expire and get handed to a different node. When the first, paused node wakes back up, it still thinks it holds the lock, and now two nodes are both acting on the same protected resource simultaneously, exactly what the lock was supposed to prevent. The fix is a fencing token: every time the lock is granted, it comes with a number that only ever increases, and the protected resource checks that number and rejects any operation carrying an old, stale token, so even if the first node comes back and tries to act, its outdated token gets refused." },
  { question: "What is PACELC and how does it extend CAP?", answer: "CAP only tells you what to do during a network partition: choose Availability or Consistency. PACELC points out that CAP doesn't cover the much more common situation where everything is actually working fine — and even then, you still face a tradeoff, this time between Latency and Consistency. For example, even with no failures at all, a write that waits for every replica to confirm it received the data (favoring consistency) will always be slower than a write that returns success the instant just one replica has it (favoring low latency, at the cost of that data possibly not being everywhere yet) — a meaningful design choice even in the best case." },
  { question: "What is chaos engineering and why deliberately break your own production system?", answer: "Chaos engineering is the deliberate practice of breaking your own production system on purpose — killing random servers, adding artificial network delays, cutting connections between services — to test whether your system actually handles failures the way you assume it does, rather than finding out during a real, unplanned, more stressful outage. Netflix popularized this with Chaos Monkey, which randomly terminated live production servers during business hours specifically, on the logic that if your system can survive that happening unexpectedly on a random Tuesday afternoon while engineers are alert and watching, it's far more likely to survive a real failure at 3am when no one's looking. The core idea is that untested resilience assumptions are really just guesses, and deliberately triggering failures turns those guesses into verified facts." },
  { question: "What are the 'fallacies of distributed computing' and why do they matter?", answer: "This is a well-known list of assumptions engineers instinctively make that are all actually false when building distributed systems: that the network is always reliable, that latency is zero, that bandwidth is infinite, that the network is secure, that its layout never changes, that there's just one administrator, that moving data costs nothing, and that the network is uniform everywhere. They matter because a design built on any one of these false assumptions works fine in a demo but eventually breaks in real production — for example, code assuming a call to another service will basically always succeed quickly will eventually be caught off guard by a slow or failed call it never planned for, causing a cascading failure." },
  { question: "How do you implement rate limiting that's correct across multiple servers, not just one?", answer: "If every server in a fleet keeps its own local counter to enforce a rate limit, say 'no more than 100 requests per minute per user,' a client can actually get far more than 100 through simply by spreading requests across multiple servers, each of which only sees a fraction of the total traffic and thinks the client is well within the limit. To enforce the limit correctly across the whole fleet, you need a single shared counter that every server checks and updates atomically — for example, using Redis's `INCR` command with an expiration, so every server increments and checks the exact same number, and the limit is enforced against the client's true total traffic, not just what any one server happened to see." },
];

export const DATABASES: ConceptSeed[] = [
  { question: "What do the four ACID properties guarantee?", answer: "Atomicity, Consistency, Isolation, and Durability are properties to ensure data integrity and reliability. Atomicity means all or nothing — either everything in a transaction is committed, or none of it is, so results stay consistent (for example, updating both the payer's and payee's account balances during a transfer). Consistency means the data across database tables stays consistent and in sync, always following the database's rules and constraints. Isolation means each transaction doesn't interfere with another — for example, while one thread is updating row 1 of a table, another thread can't update that same row at the same time. Durability means once a transaction is saved, the data stays stored even if the system crashes right after. Together, these four properties keep a database reliable and prevent data corruption." },
  { question: "Name the standard SQL transaction isolation levels and the anomaly each one prevents that the level below allows.", answer: "SQL databases offer a spectrum of isolation levels, each allowing fewer weird edge cases than the one before it, at the cost of more locking. Read Uncommitted allows 'dirty reads' — you might see another transaction's changes before it's even finished and could still roll back. Read Committed prevents that, but still allows a 'non-repeatable read,' where reading the same row twice in one transaction might show a different value because another transaction committed a change in between. Repeatable Read prevents that too, but in some databases still allows 'phantom reads,' where a brand-new row matching your query criteria can appear between two identical queries. Serializable is the strictest, preventing all of these by making transactions behave exactly as if they ran one at a time, even though they're actually running concurrently." },
  { question: "What is MVCC and what problem does it solve for concurrent reads and writes?", answer: "Multi-Version Concurrency Control (MVCC) solves a tricky problem: how do you let people read data while someone else is simultaneously writing to it, without either one blocking the other? MVCC does this by keeping multiple versions of each row around — when a transaction starts, it takes a consistent snapshot of the data as it existed at that moment, and keeps reading from that same snapshot, unaffected by other transactions writing new versions in the meantime. This is why in databases like Postgres or MySQL, a long-running report can read from a table for several seconds while other users keep updating rows in that same table, without either interfering with the other." },
  { question: "Optimistic vs pessimistic locking — when do you use each?", answer: "These are two strategies for when multiple people might try to change the same data at the same time. Pessimistic locking assumes conflicts are likely, so it locks a row the moment you start reading it with intent to change it, forcing anyone else who wants that row to wait their turn — safer under heavy contention, but people constantly wait on each other. Optimistic locking assumes conflicts are rare, so it lets you read freely and only checks at save time whether someone else modified the row in the meantime, usually via a version number, retrying if so — better throughput when conflicts are rare. For example, a shared document editor with rare simultaneous edits might use optimistic locking, while a ticket-booking system with fierce competition for the same seat might use pessimistic locking." },
  { question: "What is a write-ahead log (WAL) and why does it enable both durability and crash recovery?", answer: "A write-ahead log means the database writes down a record of every change it's about to make to a separate, append-only log file before it actually applies that change to the real data. This matters for crash recovery: if the database loses power or crashes mid-write, on restart it can replay the log to reconstruct any change that was logged but hadn't yet made it to the data files, guaranteeing no transaction the database told you was 'committed' ever gets lost. The log itself is quick and simple to write reliably, so even if the more complex process of updating the actual data files gets interrupted, the log tells the database exactly what work still needs to be redone." },
  { question: "How does a B-tree index actually speed up a lookup?", answer: "A B-tree index organizes data as a balanced, sorted tree, but unlike a typical binary tree where each node has just two children, each node in a B-tree holds many keys and child pointers at once, matching how databases read data in larger chunks from disk. This wide branching means you can find any row after reading only a handful of tree levels — like finding a word in a dictionary by flipping to roughly the right section instead of reading every page — turning a slow scan through every row into just a few quick reads. Because the tree stays sorted, it's also useful for range queries, like 'find all orders between these two dates,' and for ORDER BY, not just exact-match lookups." },
  { question: "Hash index vs B-tree index — what's the tradeoff?", answer: "A hash index converts each key into a hash value and jumps directly to the matching row, giving extremely fast equality lookups like 'find the row where id = 42' — but it stores no notion of order between keys, so it's useless for anything involving ranges, sorting, or partial matches. A B-tree index is only slightly slower for that same lookup, but because it stays sorted, it also efficiently supports range queries, ORDER BY, and prefix matching, which is why B-tree is the default, general-purpose choice for most indexes, and hash indexes are reserved for situations where you genuinely only need exact-match lookups and want that last bit of speed." },
  { question: "What's the tradeoff between a normalized and a denormalized schema?", answer: "A normalized schema stores each piece of data in exactly one place — for example, a customer's address lives only in the customers table, and every order just references that customer's ID rather than copying the address into every order row. This keeps updates cheap and consistent, but reading data spanning multiple tables often requires joining several together, which can be slower. A denormalized schema duplicates data to avoid those joins — for example, storing a copy of the address directly on each order — making reads much faster, but every write that changes that data now has to remember to update every duplicated copy, and missing even one leaves inconsistent, contradictory data." },
  { question: "What's the difference between OLTP and OLAP workloads, and why does each need a different storage layout?", answer: "OLTP (Online Transaction Processing) workloads are what a typical app does — lots of small, quick operations on individual records, like 'update this one order's status.' Row-oriented storage, where a whole row is stored together, works well here since a whole row is typically read or written at once. OLAP (Online Analytical Processing) workloads run far fewer queries, but each one scans huge amounts of data while only caring about a handful of columns — for example, 'what was our average order value last quarter' only needs the order-value column, not every column on those orders. Column-oriented storage, where each column's data is stored together, is much more efficient here since the database only reads what it actually needs and skips the rest." },
  { question: "Explain the difference between INNER, LEFT, RIGHT, and FULL OUTER joins.", answer: "These describe different ways of combining rows from two tables based on a matching condition. An INNER JOIN only returns rows where a match exists in both tables — a customer with no orders simply doesn't appear at all. A LEFT JOIN returns every row from the left table regardless of a match, filling in blanks for the right table's columns when there's no match — for example, listing every customer, including ones with zero orders, with their order details blank. A RIGHT JOIN is the same idea flipped. A FULL OUTER JOIN keeps every row from both tables, filling in blanks on whichever side is missing a match, so you see everything from both tables no matter what." },
  { question: "What is the N+1 query problem and how do you fix it?", answer: "The N+1 query problem happens when your code fetches N parent records, then loops over each one and fires off a separate query to grab its related data, ending up with N+1 total queries when a single, smarter query could have gotten everything at once. For example, fetching 100 blog posts and then querying separately for each post's author inside a loop results in 101 total database round trips, which is painfully slow. The fix is combining those into one query using a JOIN, or fetching all needed authors in a single query with something like `WHERE id IN (...)`, or using a 'data loader' pattern that automatically batches lookups happening close together in time." },
  { question: "What does a query optimizer do, and how do you use EXPLAIN to work with it?", answer: "A database's query optimizer looks at your query and, based on statistics it keeps about your tables, decides on an execution plan — which indexes to use, what order to join tables in, which join algorithm — that it estimates will be cheapest. Running EXPLAIN (or EXPLAIN ANALYZE, which actually runs the query too) shows you exactly what plan it chose, letting you catch problems before they become an incident — for example, seeing the optimizer chose a full table scan when you expected an index scan usually means you're missing an index it should have used, or the existing index isn't structured the way the query actually needs." },
  { question: "Why use a connection pool instead of opening a new DB connection per request?", answer: "Opening a fresh connection to a database every time is surprisingly expensive — it involves a network handshake, authentication, and the database allocating resources on its end — and most databases can only handle a limited number of connections open at once before performance suffers. A connection pool keeps a fixed set of connections open in advance and hands them out to your application as needed, reusing them across requests instead of opening and closing a new one each time. For example, a web server handling thousands of requests per minute reuses a pool of, say, 20 database connections rather than opening and tearing down thousands of brand-new connections, which would be both slow and risk overwhelming the database." },
  { question: "What causes replication lag and what problem can it cause for an application?", answer: "Replication lag happens because a replica database applies changes from the primary asynchronously — there's always some small delay — and if the replica is dealing with heavy load, network delays, or a large transaction, that delay can grow. This causes a real problem: if your app reads from a replica that's a few seconds behind, a user could write data, say post a comment, then immediately refresh the page and not see their own comment yet, because the replica they hit hasn't caught up. This is exactly the kind of surprising behavior that leads teams to route certain reads, like a user's own recently written data, back to the primary instead of a replica." },
  { question: "Compare the four main NoSQL data models: document, key-value, column, and graph.", answer: "There are four main flavors of NoSQL database, each optimized for a different access pattern. Key-value stores are the simplest — you get a value back instantly given its exact key, with no ability to query by anything else — great for things like caching a user's session. Document stores hold flexible, JSON-like nested records that don't require a rigid schema, fitting data that varies or evolves over time, like user profiles with optional fields. Column-family stores are optimized for enormous, sparse tables and scanning ranges by a row key, a good fit for time-series data like sensor readings. Graph databases treat connections between things as first-class, ideal for relationship-heavy questions like 'friends of friends' in a social network, or spotting fraud patterns across linked accounts." },
  { question: "What's the difference between database sharding and partitioning?", answer: "Partitioning splits a table's data into pieces within a single database instance, for example by date range, but the whole thing still lives on one machine and can be queried as one logical table. Sharding splits the data across entirely separate database instances on different machines, meaning the application itself, or a routing layer in front of the databases, has to know which specific shard holds a given piece of data before it can query it. For example, a system might shard its users table by user ID, so the application first calculates which of ten separate database servers holds a given user's data before sending the query there." },
  { question: "How do you make a schema migration safe on a large table with zero downtime?", answer: "Running a single blocking ALTER TABLE on a massive table, like adding a new required column, can lock the entire table for the duration and grind your application to a halt. A safer approach is adding the new column as optional first, which most databases handle instantly since it's just a metadata change. Then you backfill the actual data in small batches running in the background, so you're never locking the whole table at once, and only after the backfill finishes do you add stricter constraints like NOT NULL. Throughout, your application code needs to work correctly whether it's talking to the old schema or the new one, since both might be running against the database at the same time during rollout." },
  { question: "What is a covering index and why can it make a query much faster?", answer: "A covering index includes every column a particular query needs, whether it's used for filtering, selecting, or sorting, which means the database can answer the entire query using just the index itself, without ever needing to fetch the actual row from the table. Normally, an index tells the database where a matching row lives, and then it does a second lookup into the real table to get the rest of the data — a covering index skips that second step entirely. For example, if you frequently select just a user's name and email filtered by signup date, an index covering all three columns lets the database answer it directly, cutting the actual disk I/O roughly in half compared to doing that extra lookup." },
  { question: "How does a full-text search index differ from a normal B-tree index, and why can't a B-tree do full-text search well?", answer: "A B-tree index is great at finding exact values or values starting with a certain prefix, but it can't efficiently answer 'does this article contain the word elephant anywhere,' since the word could be buried anywhere in a huge block of text rather than being the value the index is organized around. Full-text search needs a different structure called an inverted index, which flips the relationship: instead of mapping documents to their content, it maps each individual word to every document that contains it, often along with extra info like position, for ranking relevance. This is exactly the kind of specialized index dedicated search engines, or a database's built-in full-text search feature, build and maintain separately from regular B-tree indexes." },
  { question: "Compare full, incremental, and point-in-time-recovery backup strategies.", answer: "A full backup is a complete copy of the entire database at one point in time — simple to restore from, but slow to create and expensive to store if taken frequently. An incremental backup only captures changes since the last backup, fast and cheap to create, but restoring means replaying an entire chain of backups in order, and if any link in that chain is missing or corrupted, the whole restore can fail. Point-in-time recovery takes a different approach: by continuously archiving the write-ahead log, it lets you restore to any exact moment you choose, like right before a bad migration ran, rather than being limited to whatever moment a scheduled backup happened to run." },
];

export const NETWORKING_OS: ConceptSeed[] = [
  { question: "TCP vs UDP — what's the core tradeoff and when do you pick UDP?", answer: "TCP and UDP are the two main ways data travels over a network, and they make opposite tradeoffs. TCP guarantees that data arrives complete, in order, and gets retransmitted if anything goes missing, using acknowledgments and a setup process before any data flows, which adds some delay. UDP just fires data off with no guarantees at all — no ordering, no confirmation it arrived — but that makes it much faster and lower-overhead. For example, a video call app uses UDP because if one tiny audio packet gets lost, you'd rather the call skip forward slightly than pause and wait for that old packet to be resent, which would make the call feel laggy — a late packet is actually worse than a missing one." },
  { question: "Walk through the TCP three-way handshake.", answer: "Before any data can flow over a TCP connection, both sides go through a quick three-step handshake to agree they're ready. First, the client sends a SYN message, saying 'I'd like to start a connection, and here's a random starting number I'll use to count my data.' The server responds with a SYN-ACK, acknowledging the client's message and sending its own starting number back. Finally, the client sends an ACK, acknowledging the server's number — and now both sides have agreed on where to start counting, similar to two people confirming 'can you hear me? yes, can you hear me? yes' before starting an important phone call." },
  { question: "At a high level, what happens during a TLS handshake before HTTPS data flows?", answer: "Before your browser can safely send data over HTTPS, it and the server perform a TLS handshake. First they agree on which TLS version and encryption method to use. Then the server presents a certificate proving its identity, which your browser checks against a trusted authority — similar to checking a photo ID against a trusted database — to make sure you're really talking to who you think you are. Finally, both sides establish a shared secret key, often via a method called Diffie-Hellman key exchange, and from that point all the actual data gets encrypted with that shared key, since it's much faster than the heavier techniques used just to set up the handshake." },
  { question: "Walk through the steps of DNS resolution for a URL you've never visited.", answer: "When you visit a website for the first time, your computer translates its domain name into a numeric IP address in stages. Your resolver first checks whether it already has the answer cached; if not, it asks a root nameserver, which points it toward the right top-level domain nameserver, for example the one responsible for all .com domains. That nameserver then points to the specific domain's own authoritative nameserver, which finally hands back the actual IP address. Each answer gets cached for a while, which is why visiting the same site again after that first lookup is usually instant — your resolver skips most of these hops because it already remembers the answer." },
  { question: "What is the OSI model and why does it still matter practically, even though real systems don't cleanly map to it?", answer: "The OSI model is a conceptual, seven-layer way of describing all the concerns involved in getting data from one machine to another — physical cables, how devices on the same local network talk, how data finds its way across different networks, how a reliable connection is maintained, and so on up through the application layer your software deals with. Real systems don't map onto these seven layers as cleanly as the model suggests, but it's still useful as shared vocabulary — for example, saying a load balancer operates 'at Layer 4' means it's only looking at IP addresses and ports to route traffic, while 'Layer 7' means it's actually reading the HTTP request itself, including the URL path and headers, to make smarter routing decisions." },
  { question: "What's the fundamental difference between a process and a thread?", answer: "A process is a running program with its own private, isolated chunk of memory that no other process can directly see into — if two processes need to communicate, they have to go through some explicit mechanism like sending messages, since they can't just reach into each other's memory. Threads live inside a single process and all share that same memory space, which makes communicating between them essentially free since they're reading and writing the same memory. But that sharing is also the risk: because multiple threads can read and write the exact same data at once, you need careful coordination, like locks, to prevent them from stepping on each other and corrupting shared data, something separate processes never have to worry about." },
  { question: "Why is a context switch expensive, and what does it actually involve?", answer: "A context switch happens when the CPU stops running one thread and starts running a different one, and it's more expensive than it sounds. The CPU has to save the current thread's state — its register values, where it was in its work — and load the next thread's saved state instead, but on top of that direct cost, the CPU's fast caches were 'warmed up' with data the old thread needed, and now the new thread has to slowly reload its own data into cache from scratch. This is exactly why having far more threads than a machine has CPU cores can actually make things slower overall — for example, spinning up 10,000 threads on an 8-core machine means the CPU spends a huge amount of time constantly switching between threads rather than getting work done." },
  { question: "What are the four necessary conditions for deadlock, and how does breaking just one prevent it?", answer: "A deadlock — where two or more processes are stuck forever waiting on each other, none able to proceed — can only happen if four conditions are all true simultaneously: mutual exclusion (a resource can only be used by one process at a time), hold-and-wait (a process holds one resource while waiting to grab another), no preemption (a resource can't be forcibly taken away), and circular wait (a chain of processes each waiting on the next, looping back to the first). Since all four have to hold at once, breaking just one is enough to prevent it entirely — for example, enforcing a strict global rule that processes must always acquire resources in the same fixed order eliminates circular wait, which alone makes deadlock impossible." },
  { question: "What is virtual memory and what does paging give you over directly addressing physical RAM?", answer: "Virtual memory gives every running process the illusion of having its own private, huge chunk of memory all to itself, isolated from other processes, even though physical RAM is actually shared and limited, with the OS falling back to disk space when RAM runs low. Paging is the mechanism that makes this practical: it divides memory into small, fixed-size chunks called pages, letting the OS map a process's virtual pages to physical frames in any arrangement, not necessarily contiguous. This flexibility means the OS can load pages into memory only when needed, and can temporarily swap out pages a process isn't currently using to make room for something more urgent, all without the process itself noticing." },
  { question: "What's the difference between a mutex and a semaphore?", answer: "A mutex allows exactly one thread to hold it at a time, and generally whichever thread locked it is responsible for unlocking it — its purpose is protecting a small section of code so only one thread runs it at once, like a single bathroom key only one person can hold. A semaphore is more flexible: it keeps a count and allows up to N threads to hold it simultaneously rather than just one, and unlike a mutex, one thread can signal it while a different thread waits on it. For example, a mutex might protect a single shared counter from being updated by two threads at once, while a semaphore might limit how many threads can simultaneously connect to a database, say capping it at 10 concurrent connections." },
  { question: "Why use a thread pool instead of spawning a new thread per task?", answer: "Creating a new thread isn't free — the OS has to allocate memory for its stack and register it with the scheduler — and if your application spins up a brand new thread for every incoming task under heavy load, you can create so many threads that you run out of memory or overwhelm the scheduler juggling them all. A thread pool keeps a fixed, reasonable number of worker threads around permanently, and incoming tasks beyond what those workers can immediately handle just wait in a queue. For example, a web server with a pool of 50 worker threads processes 5,000 requests arriving in a burst steadily 50 at a time, rather than trying to spin up 5,000 threads and grinding to a halt." },
  { question: "Name a few CPU scheduling algorithms and what each optimizes for.", answer: "Different CPU scheduling algorithms optimize for different goals. First-Come-First-Served is simplest — tasks run in the order they arrived — but one long-running task can block everything queued behind it, even short tasks that could've finished quickly. Shortest-Job-First minimizes average waiting time overall, but requires knowing in advance how long each task will take, and can leave longer tasks waiting indefinitely if short tasks keep jumping ahead of them. Round-robin gives every task a small, fixed time slice before moving to the next in a loop, keeping things responsive for interactive systems like a desktop OS, though switching so frequently costs some overall throughput compared to letting tasks run uninterrupted." },
  { question: "What is a socket, concretely?", answer: "A socket is the concrete thing your application actually interacts with to send and receive data over a network — an endpoint identified by an IP address, a port number, and a protocol, that the operating system lets your program read from and write to much like a file. Behind the scenes, the OS's networking stack handles the messy details of actually breaking your data into packets, sending them across the network, and reassembling them on the other end — the socket is just the clean interface your code gets, so you can write `socket.send(data)` without needing to know how packets actually travel across the internet." },
  { question: "What does HTTP/2 improve over HTTP/1.1, and why does that matter for web performance?", answer: "Under HTTP/1.1, browsers typically had to open a separate connection for each request they wanted to make at the same time, or send requests one after another where one slow request could hold up everything behind it — which is why older websites resorted to tricks like splitting images across several subdomains, just to trick the browser into opening more parallel connections. HTTP/2 fixes this by letting many requests and responses share a single connection simultaneously, interleaving their data as small binary chunks so nothing blocks anything else, and it also compresses the repetitive headers sent with every request. This means modern sites no longer need those old workarounds, and pages with many small resources load noticeably faster." },
  { question: "What's the practical difference between load balancing at L4 vs L7?", answer: "A load balancer at Layer 4 (the transport layer) makes routing decisions using only the IP address and port of the incoming connection, without looking at the actual content of the request — fast and able to handle any kind of traffic, not just HTTP, but it can't route based on what's actually being requested. A Layer 7 (application layer) load balancer actually opens and reads the HTTP request itself, letting it route based on things like the URL path or a cookie — for example, sending every request starting with /api/ to one set of backend servers and everything under /images/ to a completely different set optimized for static files — but that deeper inspection means more processing work per request." },
];

export const BEHAVIORAL: ConceptSeed[] = [
  { question: "What is the STAR method and why do interviewers want answers structured that way?", answer: "STAR stands for Situation, Task, Action, Result, and it's a simple framework for turning a vague claim about yourself into an actual, checkable story. Instead of saying 'I'm good at teamwork,' which nobody can verify, STAR pushes you to describe the specific situation you were in, what you needed to accomplish, exactly what you personally did, and what measurably happened as a result. For example, instead of 'I handle pressure well,' a STAR-shaped answer describes a specific project falling behind two days before launch, what you specifically did to get it back on track, and the concrete outcome — giving the interviewer something real to actually evaluate instead of a self-description they have to take on faith." },
  { question: "How should you structure an answer to 'tell me about a time you disagreed with a teammate'?", answer: "Pick a real disagreement that was actually about the work itself, not a personality clash, and show you genuinely understood their point of view before pushing back on it. Then walk through how it actually got resolved, whether through data, a compromise, or escalating to someone else to make the final call, and describe the outcome honestly, including what you'd do differently next time. Avoid picking a story where the whole point is simply that you were right and they were wrong — interviewers asking this are trying to gauge how you handle disagreement and work with others, not looking for proof that you win arguments." },
  { question: "What makes a strong answer to 'tell me about a time you failed'?", answer: "A strong answer starts with picking something that was a genuine failure with real consequences, not a humble-brag disguised as a flaw like 'I work too hard.' Own your actual specific mistake directly, without deflecting blame onto other people or circumstances, and spend most of your answer on what you actually learned and changed afterward. A weak answer either picks something trivial that didn't really matter, or spends most of its time explaining why it wasn't really your fault — both signal you're avoiding genuine self-reflection rather than demonstrating it." },
  { question: "How do you answer 'how do you prioritize when everything feels urgent'?", answer: "Describe an actual, concrete framework you genuinely use, like weighing impact against effort or simply asking 'what actually breaks if this waits until tomorrow,' rather than a vague answer like 'I just prioritize based on importance.' Back it up with a real example of applying that framework under pressure, and mention how you communicated the resulting tradeoffs to whoever's requests ended up getting pushed down the list — for example, telling a stakeholder directly 'I'm focusing on the payment bug first since it's actively costing us money, so your dashboard request will wait until tomorrow.' That communication piece is often what separates a genuinely strong answer from just an okay one." },
  { question: "What's a good structure for 'tell me about a time you persuaded others of a technical decision'?", answer: "A good structure starts by explaining the disagreement honestly, including why your position wasn't the obviously correct one to everyone else at first. Then describe specifically how you built your case — bringing actual data, building a small prototype, or directly addressing the specific concerns others had raised — rather than just repeating your own opinion louder. Be honest about the actual outcome too, including if you only partially won people over or had to compromise — a story that admits some nuance in the outcome generally reads as far more credible than a suspiciously clean, total victory." },
  { question: "How should you talk about receiving critical feedback in an interview?", answer: "Pick a specific example of feedback that actually stung a little when you first heard it, not a safe, generic one like being told to 'be more confident,' which doesn't reveal how you handle real criticism. Show you took the feedback seriously and reflected on it rather than immediately getting defensive, then describe the concrete, specific change you actually made afterward. Interviewers ask this to check for coachability, so a story with zero real discomfort in it usually reads as evasive rather than reassuring." },
  { question: "What should a good 'tell me about a time you mentored someone' answer emphasize?", answer: "A good answer focuses less on how much you personally knew and more on how you adapted your approach to that particular person's own learning style, gaps, or pace — mentoring is fundamentally about them, not about showcasing your own expertise. Describe a measurable change in their skill or confidence over time, like them going from needing help with a certain task to confidently doing it independently. A generic answer like 'I answered their questions whenever they had them' doesn't demonstrate mentoring skill — it demonstrates being a helpful, responsive coworker, which is a different and much lower bar." },
  { question: "How do you handle a question about working with ambiguous or incomplete requirements?", answer: "Describe how you actually took action to reduce the ambiguity rather than either freezing up waiting for more clarity, or barreling ahead making unchecked assumptions. That might mean asking specific, targeted clarifying questions rather than a vague 'can you tell me more,' making a reasonable documented assumption and checking it with the right person early before building too much on top of it, or building a small, quick prototype specifically to surface requirements that weren't obvious until you actually started building something real." },
  { question: "What's a productive way to answer 'tell me about a conflict with a manager or stakeholder'?", answer: "Keep it professional and specific — a genuine disagreement about the right approach, priority, or scope, described concretely rather than vaguely. Show you raised it directly and respectfully with that person, rather than quietly working around them or venting to other people instead of addressing it head-on. Be honest about how it was actually resolved too, including if you ultimately deferred to their decision after making your case clearly — an honest, nuanced ending generally reads as far more mature than claiming you were vindicated every time." },
  { question: "How do you talk about working with an underperforming teammate without sounding like you're throwing them under the bus?", answer: "Focus the story on what you specifically did about it — offering targeted help with something specific they were struggling with, adjusting how you communicated with them, or escalating appropriately if it was genuinely affecting the team — rather than spending the answer cataloguing everything wrong with their performance. The interviewer is assessing your judgment and empathy here, not conducting an informal performance review of a coworker who isn't in the room to defend themselves." },
  { question: "What's a strong way to answer 'tell me about a time you missed a deadline'?", answer: "A strong answer owns the miss plainly and directly, without reflexively blaming scope changes or other people as the very first thing you say. Explain concretely what you actually did once you realized the deadline was at risk — communicating early instead of hoping it would work out, renegotiating scope or timeline, or asking for help before it was too late — then describe a real, specific process change you made afterward so you'd catch a similar risk earlier next time, showing this wasn't just a one-off apology but an actual lesson you internalized." },
  { question: "How do you effectively communicate a technical tradeoff to a non-technical stakeholder?", answer: "Translate the tradeoff into terms they actually care about, like cost, timeline, risk, or how it affects the end user, rather than explaining the underlying technical mechanism itself, which they likely don't need to understand in detail. Give them a small, manageable number of concrete options rather than an open-ended, unstructured problem, and state your own recommendation clearly rather than just listing pros and cons and leaving the entire decision to them — for example, saying 'I'd recommend option B because it ships two weeks faster with only a small risk, here's why,' rather than just presenting a neutral list and walking away." },
  { question: "What makes a good answer to 'tell me about a time you took initiative without being asked'?", answer: "A strong answer picks an example where you identified a real, meaningful problem that other people around you hadn't already flagged, made a clear case for why it actually mattered enough to be worth the effort, rather than just doing something extra because it felt proactive. Then describe the actual, concrete impact once you followed through. A genuinely strong initiative story shows judgment about what's worth doing, not just a generic eagerness to do more work — for example, noticing a recurring manual process was quietly costing the team hours every week and building a small tool to automate it, rather than just volunteering for extra tasks indiscriminately." },
  { question: "How should you answer a question about handling scope creep on a project?", answer: "Describe how you made the growing scope visible early to the people who needed to know, rather than silently absorbing all the extra work and either burning out or quietly missing the original deadline without ever raising a flag. Then explain how you explicitly renegotiated the timeline, scope, or resources with whoever requested the additional work — for example, going back to a stakeholder and saying 'these three new requirements will push our deadline out by a week, or we can cut one of the original items to stay on track — which would you prefer?' This shows you protect the health of the project rather than reflexively saying yes to every new request." },
  { question: "How do you give a genuine, specific answer to 'why do you want to work here'?", answer: "A genuine answer anchors itself to something concrete and specific about that particular company — a specific product decision, an engineering challenge they're known for tackling, or a technical direction you've actually looked into — rather than something generic that could apply to any company. It should also connect that specific thing back to something specific about your own background, skills, or goals, showing a genuine two-way fit rather than one-sided flattery. Vague answers like 'you have a great culture' or 'I'm excited by your mission,' that could be copy-pasted into an application for any company, signal you didn't do any real research before showing up." },
];

const CATEGORY_GROUPS: [Category, ConceptSeed[]][] = [
  ["System Design", SYSTEM_DESIGN],
  ["Data Structures & Algorithms", DSA],
  ["Distributed Systems", DISTRIBUTED],
  ["Databases", DATABASES],
  ["Networking & OS", NETWORKING_OS],
  ["Behavioral", BEHAVIORAL],
];

// Interleaves the category groups proportionally to their size (a group with
// 50 items appears roughly 3.3x as often as one with 15) while preserving
// each group's internal order — a fractional round-robin (Bresenham-style):
// every group accumulates its own share (size/total) each step, and the
// group with the largest accumulated share is picked next and decremented by
// 1, so error never builds up in one direction the way naive rounding would.
export function buildTheorySchedule(): Concept[] {
  const total = CATEGORY_GROUPS.reduce((sum, [, items]) => sum + items.length, 0);
  const indices = CATEGORY_GROUPS.map(() => 0);
  const share = CATEGORY_GROUPS.map(([, items]) => items.length / total);
  const acc = CATEGORY_GROUPS.map(() => 0);
  const result: Concept[] = [];

  for (let day = 1; day <= total; day++) {
    let best = -1;
    for (let g = 0; g < CATEGORY_GROUPS.length; g++) {
      acc[g]! += share[g]!;
      if (indices[g]! < CATEGORY_GROUPS[g]![1].length && (best === -1 || acc[g]! > acc[best]!)) {
        best = g;
      }
    }
    const [category, items] = CATEGORY_GROUPS[best]!;
    const seed = items[indices[best]!]!;
    result.push({ day, category, question: seed.question, answer: seed.answer });
    indices[best]! += 1;
    acc[best]! -= 1;
  }

  return result;
}

export const TOTAL_DAYS = buildTheorySchedule().length;
